// ============================================================
// LOGIN SYSTEM
// ============================================================
const DEFAULT_PW=SC.defaultPw;
let passwords={};
let currentRole=null; // 'coach' or 'player'
let currentPlayerId=null;
let pinEntry='';
let _pinChecking=false;

function switchLogin(mode){
  // With player login off there is no toggle and no player section to switch to, so a
  // stray call (the door check-in prompt makes one) is a no-op rather than a null crash.
  if(mode!=='coach'&&!PLAYER_LOGIN_ON)return;
  document.querySelectorAll('.login-toggle-btn').forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('.login-section').forEach(s=>s.classList.remove('active'));
  const _coachBtn=document.querySelector('.login-toggle-btn:nth-child(1)');
  const _playerBtn=document.querySelector('.login-toggle-btn:nth-child(2)');
  if(mode==='coach'){
    if(_coachBtn)_coachBtn.classList.add('active');
    document.getElementById('login-coach').classList.add('active');
  }else{
    if(_playerBtn)_playerBtn.classList.add('active');
    document.getElementById('login-player').classList.add('active');
    populatePlayerLogin();
  }
}
// ── HYBRID PLAYER LOGIN ──────────────────────────────────────
// A school migrates to CourtSense accounts one player at a time, so both paths have to
// work at once on the same shell. Flipping SC.emailLogin switches a whole roster in one
// go, which would lock out everyone who had not claimed yet.
//
// There is no new config. The behavior is data driven: a shell with SC.emailLogin false
// gets the hybrid, and each player's own accountId decides which form they see. A school
// needs no shell edit to start, and none to finish.
//
// Only one credential form is ever visible, so there is never a double form to choose
// between. The name picker stays the default. Selecting a player who has claimed swaps
// the form to email and password and says why, and anyone can switch by hand.
let _hsAcctManual=false;
function hsRefreshLoginMode(){
  const sel=document.getElementById('login-player-select');
  const p=(sel&&sel.value)?gP(sel.value):null;
  const pickedClaimed=!!(p&&p.accountId);
  const useAcct=_hsAcctManual||pickedClaimed;
  const pick=document.getElementById('hs-pick-block');
  const legacy=document.getElementById('hs-legacy-block');
  const acct=document.getElementById('hs-acct-block');
  const note=document.getElementById('hs-acct-note');
  const link=document.getElementById('hs-login-toggle');
  if(!legacy||!acct)return;                       // SC.emailLogin shells have neither
  if(pick)pick.style.display=_hsAcctManual?'none':'';
  legacy.style.display=useAcct?'none':'';
  acct.style.display=useAcct?'':'none';
  if(note)note.textContent=(pickedClaimed&&!_hsAcctManual)
    ? ((p.firstName||'You')+' already set up a CourtSense account. Log in with that email and password.')
    : '';
  if(link)link.textContent=_hsAcctManual?'Use my name and the team password instead':'I have a CourtSense account';
}
function hsToggleLoginMode(){
  _hsAcctManual=!_hsAcctManual;
  const e=document.getElementById('pw-error');if(e)e.textContent='';
  const e2=document.getElementById('hs-pw-error');if(e2)e2.textContent='';
  hsRefreshLoginMode();
}
function onPickPlayer(){
  const e=document.getElementById('pw-error');if(e)e.textContent='';
  hsRefreshLoginMode();
}

function populatePlayerLogin(){
  const sel=document.getElementById('login-player-select');
  if(!sel)return; // email-login mode (SC.emailLogin) has no name dropdown
  const cur=sel.value;
  sel.innerHTML='<option value="">— Choose Player —</option>';
  const sorted=[...D.players].sort((a,b)=>a.court-b.court||a.lastName.localeCompare(b.lastName));
  sorted.forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.firstName+' '+p.lastName;sel.appendChild(o);});
  if(cur)sel.value=cur;
  // The roster arrives asynchronously, so re-run the mode check once names exist. A
  // restored selection whose player has since claimed lands on the right form.
  hsRefreshLoginMode();
}
async function pinPress(n){
  if(_pinChecking)return;                       // ignore digit presses while a request is in flight
  if(pinEntry.length>=4)return;
  pinEntry+=n;
  updatePinDots();
  if(pinEntry.length===4){
    _pinChecking=true;
    const errEl=document.getElementById('pin-error');
    if(errEl)errEl.textContent='Checking...';
    let j=null, netErr=false;
    try{
      const r=await fetch(AUTH_WORKER+'/auth/coach-verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dbRoot:DB_ROOT,pin:pinEntry})});
      j=await r.json().catch(()=>null);
    }catch(e){netErr=true;}
    if(j&&j.ok){
      sessionStorage.setItem('csCoachSession',JSON.stringify({token:j.token,dbRoot:DB_ROOT,expiresAt:j.expiresAt}));
      if(errEl)errEl.textContent='';
      _pinChecking=false;
      loginAsCoach();
      return;
    }
    if(netErr){
      if(errEl)errEl.textContent='Could not reach the server. Try again.';
      pinEntry='';updatePinDots();_pinChecking=false;
    }else if(j&&j.code==='not_set'){
      if(errEl)errEl.textContent='No PIN set for this school. Contact support.';
      pinEntry='';updatePinDots();_pinChecking=false;
    }else if(j&&j.code==='server_error'){
      if(errEl)errEl.textContent='Something is wrong on our end, not your password. Try again in a few minutes.';
      pinEntry='';updatePinDots();_pinChecking=false;
    }else if(j&&j.code==='rate_limited'){
      if(errEl)errEl.textContent='Too many attempts. Try again in a few minutes.';
      pinEntry='';updatePinDots();_pinChecking=false;
    }else{
      if(errEl)errEl.textContent='Incorrect PIN';
      setTimeout(()=>{pinEntry='';updatePinDots();const e2=document.getElementById('pin-error');if(e2)e2.textContent='';_pinChecking=false;},800);
    }
  }
}
function pinBack(){pinEntry=pinEntry.slice(0,-1);updatePinDots();document.getElementById('pin-error').textContent='';}
// Reveal the shared PIN pad on account-login schools, where the per-exec email
// sign-in is primary and the pad starts hidden behind a small link. One-way per
// visit: once revealed it stays until the overlay is rebuilt. Verification,
// sessions, and error handling are untouched; this only toggles visibility.
function showSharedPinPad(){
  const w=document.getElementById('pin-pad-wrap'); if(w)w.style.display='';
  const l=document.getElementById('pin-alt-link'); if(l)l.style.display='none';
}
function updatePinDots(){document.querySelectorAll('.login-pin-dot').forEach((d,i)=>{d.classList.toggle('filled',i<pinEntry.length);});}

function loginAsCoach(){
  currentRole='coach';currentPlayerId=null;
  // An exec who scanned the door code lands here; say so rather than dropping it silently.
  if(typeof processPendingTryout==='function')processPendingTryout();
  // Door mode is a full-screen display, so a refresh on the door phone has to come back to it.
  if(typeof tsDoorRestore==='function')tsDoorRestore();
  document.getElementById('login-overlay').classList.add('hidden');
  document.getElementById('app-wrapper').style.display='block';
  document.getElementById('coach-content').style.display='block';
  document.getElementById('player-portal').style.display='none';
  // Per-exec sessions carry the exec's name (stored at exec login); the shared-PIN
  // path has none and keeps the generic label. Covers fresh logins and restores.
  let _execSess=null; try{_execSess=JSON.parse(sessionStorage.getItem('csCoachSession'));}catch(e){}
  document.getElementById('header-username').textContent=(_execSess&&_execSess.execName)?_execSess.execName:COACH_LABEL;
  document.querySelector('.tabs').style.display='flex';
  refreshCurrent();
  // Club only: the Broadcast tab is active on entry but the statically-active pane is
  // tab-duals, so content and tab disagree on first paint. Fire the existing tab handler
  // on the active button inside the VISIBLE manage bar (Broadcast) so it activates
  // tab-broadcast and deactivates tab-duals. Manage-bar-scoped selector avoids the hidden
  // recruiting tab. HS configs (chatEnabled false) are untouched and keep gameday/duals.
  if(SC.chatEnabled){
    const bc=document.querySelector('#sub-tabs-manage .tab.active');
    if(bc)bc.click();
  }
  else if(!SC.tiersEnabled){
    // HS four-tab nav lands on Duals with Dashboard active, but the statically-active pane is
    // tab-duals. Click the active tab (Dashboard) so the pane and the tab agree on first paint.
    const hd=document.querySelector('.tab.active');
    if(hd)hd.click();
  }
}

// Admin cross-school entry: store a worker-issued coach session token (from
// /auth/admin-coach-session) and enter coach mode. Driven by the ?csadmin=<token> boot
// path in initFB. The token is a real, expiring, server-validated session, not a flag.
function adminEnterSchool(token, expiresAt){
  sessionStorage.setItem('csCoachSession',JSON.stringify({token:token,dbRoot:DB_ROOT,expiresAt:expiresAt||null}));
  loginAsCoach();
}
function playerLogin(){
  // Closed at the shell. Guarded here too, so the console is not a way around the UI.
  if(!PLAYER_LOGIN_ON)return;
  const pid=document.getElementById('login-player-select').value;
  const pw=document.getElementById('login-pw').value;
  if(!pid){document.getElementById('pw-error').textContent='Select your name';return;}
  // A claimed player has their own CourtSense password, so the team password must stop
  // working for them. Leaving both live would mean two credentials for one person,
  // which is the thing claiming was meant to end.
  const _pSel=gP(pid);
  if(_pSel&&_pSel.accountId){
    hsRefreshLoginMode();
    const _e=document.getElementById('hs-pw-error');
    if(_e)_e.textContent='You already set up a CourtSense account. Log in with that email and password.';
    return;
  }
  if(!pw){document.getElementById('pw-error').textContent='Enter your password';return;}
  const storedPw=_storedPw(pid)||DEFAULT_PW;
  if(pw!==storedPw){document.getElementById('pw-error').textContent='Incorrect password';return;}
  document.getElementById('pw-error').textContent='';
  currentRole='player';currentPlayerId=pid;
  sessionStorage.setItem('leonAuth',JSON.stringify({role:'player',pid}));
  document.getElementById('login-overlay').classList.add('hidden');
  document.getElementById('app-wrapper').style.display='block';
  document.getElementById('coach-content').style.display='none';
  document.getElementById('player-portal').style.display='block';
  document.getElementById('player-portal').classList.add('active');
  document.querySelector('.tabs').style.display='none';
  const p=gP(pid);
  document.getElementById('header-username').textContent=p?p.firstName+' '+p.lastName:'Player';
  renderPlayerPortal();
  ppAfterLogin();
}
// Email + password player login (SC.emailLogin schools only, e.g. FSU Grass). Verifies
// the CourtSense account server-side via the worker (same fetch/error convention as the
// coach PIN path), then resolves the club roster record by matching accountId. Sets
// currentPlayerId to the CLUB record id so every downstream consumer is unchanged.
let _emailLoginBusy=false;
async function playerLoginEmail(){
  if(_emailLoginBusy)return;
  // The hybrid block's ids win when present, so a school shell reads its account form
  // rather than the legacy password field sitting beside it. An SC.emailLogin shell has
  // no hs-* ids and falls through to the originals, unchanged.
  const emailEl=document.getElementById('hs-login-email')||document.getElementById('login-email');
  const pwEl=document.getElementById('hs-login-pw')||document.getElementById('login-pw');
  const errEl=document.getElementById('hs-pw-error')||document.getElementById('pw-error');
  const email=(emailEl?emailEl.value:'').trim().toLowerCase();
  const pw=pwEl?pwEl.value:'';
  if(!email){if(errEl)errEl.textContent='Enter your email';return;}
  if(!pw){if(errEl)errEl.textContent='Enter your password';return;}
  _emailLoginBusy=true;
  const btn=document.getElementById('hs-player-login-btn')||document.getElementById('player-login-btn');
  if(btn)btn.disabled=true;
  if(errEl)errEl.textContent='Checking...';
  let j=null, netErr=false;
  try{
    const r=await fetch(AUTH_WORKER+'/auth/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rosterPath:'tally_kotb_pickup/players',email:email,password:pw})});
    j=await r.json().catch(()=>null);
  }catch(e){netErr=true;}
  const done=()=>{_emailLoginBusy=false;if(btn)btn.disabled=false;};
  if(netErr){if(errEl)errEl.textContent='Could not reach the server. Try again.';done();return;}
  if(!j||j.ok!==true){
    if(errEl)errEl.textContent=
      (j&&j.code==='rate_limited')?'Too many attempts. Try again in a few minutes.'
      :(j&&j.code==='server_error')?'Something is wrong on our end, not your password. Try again in a few minutes.'
      :'Incorrect email or password';
    done();return;
  }
  // Verified. Resolve the club roster record by matching accountId to the account id.
  const accountId=j.player&&j.player.id;
  const rec=accountId?D.players.find(p=>p.accountId===accountId):null;
  // Names the actual tenant rather than hardcoding one school, and points at whoever
  // runs that program: an exec at the club, a coach at a school.
  if(!rec){
    const _who=SC.displayName||SC.shortName||SC.schoolName||'this team';
    const _ask=SC.tiersEnabled?'Contact the exec team.':'Ask your coach to send you an invite.';
    // Scanned at the door with a CourtSense account but no club record: the application is
    // the way in, and it carries the held session id so finishing it checks them in.
    const _held=(typeof tryoutHoldGet==='function')?tryoutHoldGet():null;
    if(errEl){
      if(_held&&SC.applyUrl){
        errEl.innerHTML='This account is not linked to a '+_who+' roster record yet. '
          +'<a href="javascript:void(0)" onclick="openApplyPage()" style="color:var(--red);font-weight:700;text-decoration:underline;">Apply now</a>'
          +' and you are checked in when you finish.';
      } else {
        errEl.textContent='This account is not linked to a '+_who+' roster record yet. '+_ask;
      }
    }
    done();return;
  }
  if(errEl)errEl.textContent='';
  done();
  // Session + portal entry mirror playerLogin. currentPlayerId is the CLUB record id, not the account id.
  currentRole='player';currentPlayerId=rec.id;
  sessionStorage.setItem('leonAuth',JSON.stringify({role:'player',pid:rec.id}));
  document.getElementById('login-overlay').classList.add('hidden');
  document.getElementById('app-wrapper').style.display='block';
  document.getElementById('coach-content').style.display='none';
  document.getElementById('player-portal').style.display='block';
  document.getElementById('player-portal').classList.add('active');
  document.querySelector('.tabs').style.display='none';
  document.getElementById('header-username').textContent=rec.firstName+' '+rec.lastName;
  renderPlayerPortal();
  ppAfterLogin();
}
// Exec email + password login (SC.emailLogin schools only). Verifies the CourtSense
// account against the school's exec list SERVER-SIDE via /auth/exec-session and, on
// success, stores the SAME csCoachSession shape the PIN path stores (token, dbRoot,
// expiresAt) plus additive identity fields (accountId, role, execName), so session
// restore, PIN change, and every /hs/* consumer work unchanged. Fetch and error
// conventions mirror playerLoginEmail and the PIN pad.
let _execLoginBusy=false;
async function execLoginEmail(){
  if(_execLoginBusy)return;
  const emailEl=document.getElementById('exec-login-email');
  const pwEl=document.getElementById('exec-login-pw');
  const errEl=document.getElementById('exec-login-error');
  const email=(emailEl?emailEl.value:'').trim().toLowerCase();
  const pw=pwEl?pwEl.value:'';
  if(!email){if(errEl)errEl.textContent='Enter your email';return;}
  if(!pw){if(errEl)errEl.textContent='Enter your password';return;}
  _execLoginBusy=true;
  const btn=document.getElementById('exec-login-btn');
  if(btn)btn.disabled=true;
  if(errEl)errEl.textContent='Checking...';
  let j=null, netErr=false;
  try{
    const r=await fetch(AUTH_WORKER+'/auth/exec-session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dbRoot:DB_ROOT,email:email,password:pw})});
    j=await r.json().catch(()=>null);
  }catch(e){netErr=true;}
  const done=()=>{_execLoginBusy=false;if(btn)btn.disabled=false;};
  if(netErr){if(errEl)errEl.textContent='Could not reach the server. Try again.';done();return;}
  if(!j||j.ok!==true){
    if(errEl)errEl.textContent=
      (j&&j.code==='rate_limited')?'Too many attempts. Try again in a few minutes.'
      :(j&&j.code==='server_error')?'Something is wrong on our end, not your password. Try again in a few minutes.'
      :(j&&j.code==='not_exec')?"This account is not on the school's exec list."
      :'Incorrect email or password';
    done();return;
  }
  // Name the session from the club roster when the account is on it; the header and
  // the Exec Access card read this. Not being on the roster is fine (the exec list
  // is the authority), so an off-roster exec just keeps the generic label.
  const rec=D.players.find(p=>p.accountId===j.accountId);
  const execName=rec?((rec.firstName||'')+' '+(rec.lastName||'')).trim():'';
  sessionStorage.setItem('csCoachSession',JSON.stringify({token:j.token,dbRoot:DB_ROOT,expiresAt:j.expiresAt,accountId:j.accountId,role:j.role,execName:execName}));
  if(errEl)errEl.textContent='';
  if(pwEl)pwEl.value='';
  done();
  loginAsCoach();
}
function logout(){
  currentRole=null;currentPlayerId=null;pinEntry='';
  // Door mode is a full-screen layer above the app; signing out has to take it down with them.
  if(typeof tsDoorClose==='function')tsDoorClose();
  // Kings Night listeners belong to the session that is ending.
  if(typeof ptpDetachAll==='function'){ ptpDetachAll(); var _ppk=document.getElementById('pp-kings'); if(_ppk)_ppk.innerHTML=''; }
  if(typeof ptDetach==='function')ptDetach();
  if(typeof tnDetach==='function')tnDetach(); // the exec tournament card's listener
  sessionStorage.removeItem('leonAuth');
  sessionStorage.removeItem('csCoachSession');
  updatePinDots();
  document.getElementById('login-overlay').classList.remove('hidden');
  document.getElementById('app-wrapper').style.display='none';
  document.getElementById('coach-content').style.display='none';
  document.getElementById('player-portal').style.display='none';
  document.getElementById('player-portal').classList.remove('active');
  document.getElementById('pin-error').textContent='';
  document.getElementById('pw-error').textContent='';
  document.getElementById('login-pw').value='';
}
async function autoLogin(){
  // Coach: validate the stored session token server-side before entering coach mode.
  // Never trust a bare flag; a forged sessionStorage entry fails the worker check.
  try{
    const cs=JSON.parse(sessionStorage.getItem('csCoachSession'));
    if(cs&&cs.token&&cs.dbRoot===DB_ROOT&&(!cs.expiresAt||cs.expiresAt>Date.now())){
      const r=await fetch(AUTH_WORKER+'/auth/coach-session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dbRoot:DB_ROOT,token:cs.token})});
      const j=await r.json().catch(()=>null);
      if(j&&j.ok){loginAsCoach();return;}
      sessionStorage.removeItem('csCoachSession');
    }
  }catch(e){sessionStorage.removeItem('csCoachSession');}
  // Player: unchanged, restored from leonAuth. A session minted before player login was
  // turned off is dropped rather than honored, otherwise flipping the shell would leave
  // anyone mid-session still inside.
  if(!PLAYER_LOGIN_ON){ sessionStorage.removeItem('leonAuth'); return; }
  try{
    const auth=JSON.parse(sessionStorage.getItem('leonAuth'));
    if(!auth)return;
    if(auth.role==='player'&&auth.pid){currentPlayerId=auth.pid;currentRole='player';
      document.getElementById('login-overlay').classList.add('hidden');
      document.getElementById('app-wrapper').style.display='block';
      document.getElementById('coach-content').style.display='none';
      document.getElementById('player-portal').style.display='block';
      document.getElementById('player-portal').classList.add('active');
      document.querySelector('.tabs').style.display='none';
      const p=gP(auth.pid);
      document.getElementById('header-username').textContent=p?p.firstName+' '+p.lastName:'Player';
      renderPlayerPortal();
      ppAfterLogin();
    }
  }catch(e){}
}

async function changePassword(){
  // The team password is the only thing this changes, and that login is closed.
  if(!PLAYER_LOGIN_ON)return;
  if(!currentPlayerId)return;
  const cur=document.getElementById('t-pw-current').value;
  const newPw=document.getElementById('t-pw-new').value;
  const confirm=document.getElementById('t-pw-confirm').value;
  const storedPw=_storedPw(currentPlayerId)||DEFAULT_PW;
  if(cur!==storedPw){toast('Current password is incorrect');return;}
  if(!newPw||newPw.length<4){toast('New password must be at least 4 characters');return;}
  if(newPw!==confirm){toast('Passwords do not match');return;}
  // Writes the pw leaf rather than the node value, so emailPrefs beside it survives.
  // A record still holding a bare string is replaced by this object, which is correct:
  // the string it held is the password being changed.
  const ok=await _pwNodeUpdate(currentPlayerId,{pw:newPw});
  // A password change is worth confirming honestly. This used to toast success even
  // when the write was rejected, which would leave a player locked to the old one.
  if(!ok){toast('Password did not save. Try again.');return;}
  toast('Password updated!');
  document.getElementById('t-pw-current').value='';document.getElementById('t-pw-new').value='';document.getElementById('t-pw-confirm').value='';
}

// ============================================================
// PLAYER PORTAL RENDERING
// ============================================================
let ppStatView='official';
function ppSetStatView(view,btn){
  ppStatView=view;
  document.querySelectorAll('#pp-stat-toggle .filter-btn').forEach(b=>b.classList.remove('active'));
  if(btn)btn.classList.add('active');
  renderPlayerPortal();
}
// Roster tier filter state (Grass Club only). Mirrors ppStatView: module-level selection, toggle .active, re-render.
let rosterTierFilter='all';
function setRosterTierFilter(v,btn){
  rosterTierFilter=v;
  document.querySelectorAll('#roster-tier-toggle .filter-btn').forEach(b=>b.classList.remove('active'));
  if(btn)btn.classList.add('active');
  renderRoster();
}
// Player-side tier request (Grass Club only). Writes to the SEPARATE tier_requests node; never touches players/{id}.tier.
// Mutates the in-memory copy so it reflects immediately in demo mode, where fbSet is a no-op.
function playerRequestTier(choice){
  if(!currentPlayerId)return;
  const rec={tier:choice,ts:Date.now()};
  fbSet('tier_requests/'+currentPlayerId,rec);
  if(!D.tierRequests)D.tierRequests={};
  D.tierRequests[currentPlayerId]=rec;
  const TIER_LABELS={gold:'Gold',garnet:'Garnet'};
  toast('Requested '+(TIER_LABELS[choice]||choice)+'. Your coach will review it.');
  renderPlayerPortal();
}
// ---- Club member: rating under the name, and the tab they land on -----------------
// The member's own platform rating record in tally_kotb_pickup/ratings, found the way
// resolveClubRating finds it: the one record tagged with their accountId, else the single
// untagged record for their name. A number shows only when Ratings.isRated says so (5 rated
// games or a TruVolley seed on the record), the same test pickup uses. With no record at all, a
// TruVolley seed from club signup shows its seed rating. Anything else is "Unrated", and a
// failed read shows nothing. Read once per login and cached.
var _ppRating=null;       // { pid, text } once resolved; text '' after a failed read
var _ppRatingLoading=null;
// A member's own rating record: the one tagged with their accountId, else the single untagged
// record for their name. Returns the record, null when there is none, or 'ambiguous' when more
// than one could be theirs (never guessed).
function ppFindRatingRecord(p,R){
  var acct=(typeof p.accountId==='string'&&p.accountId)?p.accountId:'';
  if(acct){
    var tagged=Object.keys(R).filter(function(k){ return R[k]&&R[k].playerId===acct; });
    if(tagged.length>1) return 'ambiguous';
    if(tagged.length===1) return R[tagged[0]];
  }
  var nk=Ratings.nameKey(((p.firstName||'')+' '+(p.lastName||'')).trim()||String(p.name||''));
  if(!nk) return null;
  var byName=Object.keys(R).filter(function(k){
    var r=R[k]; if(!r||typeof r!=='object'||(typeof r.playerId==='string'&&r.playerId)) return false;
    return k===nk||(r.name&&Ratings.nameKey(r.name)===nk);
  });
  if(byName.length>1) return 'ambiguous';
  return byName.length===1?R[byName[0]]:null;
}
function ppRatingText(p,ratings){
  if(!window.Ratings||typeof Ratings.nameKey!=='function'||typeof Ratings.isRated!=='function') return '';
  var rec=ppFindRatingRecord(p,ratings||{});
  if(rec==='ambiguous') return 'Unrated';
  if(rec) return (Ratings.isRated(rec)&&typeof rec.rating==='number')?'Rating '+Math.round(rec.rating):'Unrated';
  if(typeof p.truVolley==='number'&&typeof p.rating==='number') return 'Rating '+Math.round(p.rating);
  return 'Unrated';
}
function ppRenderRating(){
  var el=document.getElementById('pp-rating'); if(!el) return;
  if(!SC.tiersEnabled||currentRole!=='player'||!currentPlayerId){ el.textContent=''; return; }
  var pid=currentPlayerId;
  if(_ppRating&&_ppRating.pid===pid){ el.textContent=_ppRating.text; return; }
  el.textContent='';
  if(!db||_ppRatingLoading===pid) return;
  _ppRatingLoading=pid;
  db.ref('tally_kotb_pickup/ratings').once('value').then(function(s){
    var p=gP(pid); if(!p) throw new Error('member not found');
    _ppRating={pid:pid, text:ppRatingText(p,s.val()||{})};
  }).catch(function(e){
    console.warn('member rating read failed',e);
    _ppRating={pid:pid, text:''};
  }).then(function(){
    if(_ppRatingLoading===pid) _ppRatingLoading=null;
    if(currentPlayerId===pid) ppRenderRating();
  });
}
// After a member logs in or a session is restored: re-read their rating, and on the club open
// Club Life (the club chats) instead of My Info. Every other shell keeps its default tab.
function ppAfterLogin(){
  // A read the portal render just started for this member is already fresh; do not start another.
  if(_ppRatingLoading!==currentPlayerId){ _ppRating=null; ppRenderRating(); }
  if(!SC.tiersEnabled) return;
  var btn=document.querySelector('.pp-tab-btn[onclick*="clublife"]');
  if(btn) switchPPTab('clublife',btn);
}
// ---- Kings Night season leaderboard and nightly results (club) ------------------------
// Execs (Manage > Stats) and members (the portal's Kings Night tab) get the same two views, built
// only from the practice tournaments already in the club snapshot (D.practiceTournaments). No
// writes and no rating numbers. Season totals count final nights only; one night's standings come
// from ptStandingsIn, the helper the live night uses.
// Periods are academic semesters taken from each night's date, never the app's seasonId: Spring is
// January 1 to May 31, Fall is June 1 to December 31 (a June or July onboarding night counts toward
// that year's Fall; there is no Summer). "All time" covers every final night. Ratings are not
// involved and never reset.
// Who shows on the leaderboard to members: anyone with 5 Kings Night games ALL TIME (final nights,
// every pool and squad), or a TruVolley player from their first night (a signup seed on the roster
// record, or seededFromTruVolley on their rating record), so a returning player never drops off a new
// semester's board. Members always see their own totals; execs see every row, marked when it is
// under that line.
var KN_MIN_GAMES=5;
var KN_POOL_LABELS={kings:'Kings', queens:'Queens', mixed:'Coed', all:'All'};
var _knState={
  exec:{view:'season', period:null, pool:'all', squad:'all', sortKey:null, sortDir:-1, night:null},
  player:{view:'season', period:null, pool:'all', squad:'all', sortKey:null, sortDir:-1, night:null}
};
var _knSeeded=null;        // { rosterId: true } for rating records carrying seededFromTruVolley
var _knSeededLoading=false;
function knPoolsOf(m){ return (m&&m.format==='kq')?['kings','queens']:['mixed']; }
// The semester a YYYY-MM-DD date falls in: { key:'2026-fall', label:'Fall 2026', order } or null.
function knSemesterOf(date){
  var m=/^(\d{4})-(\d{2})/.exec(String(date||''));
  if(!m) return null;
  var y=parseInt(m[1],10), mo=parseInt(m[2],10);
  return mo<=5?{key:y+'-spring', label:'Spring '+y, order:y*10+1}:{key:y+'-fall', label:'Fall '+y, order:y*10+2};
}
function knCurrentSemester(){ return knSemesterOf(td()); }
// The period a view shows: a semester key, or 'all'. Null in the state means the current semester.
function knPeriodOf(st){ return st.period||knCurrentSemester().key; }
// Every final night, newest first, optionally limited to one semester key ('all' for every night).
function knFinalNights(period){
  var T=D.practiceTournaments||{};
  return Object.keys(T).map(function(tid){ return {tid:tid, data:T[tid], meta:(T[tid]&&T[tid].meta)||{}}; })
    .filter(function(n){
      if(n.meta.status!=='final') return false;
      if(!period||period==='all') return true;
      var s=knSemesterOf(n.meta.date); return !!s&&s.key===period;
    })
    .sort(function(a,b){ return String(b.meta.date||'').localeCompare(String(a.meta.date||''))||(a.tid<b.tid?1:a.tid>b.tid?-1:0); });
}
// The period choices: the current semester, each earlier semester with a final night (newest
// first), then All time.
function knPeriods(){
  var cur=knCurrentSemester(), seen={}, list=[cur];
  seen[cur.key]=1;
  knFinalNights('all').forEach(function(n){
    var s=knSemesterOf(n.meta.date);
    if(s&&!seen[s.key]){ seen[s.key]=1; list.push(s); }
  });
  list.sort(function(a,b){ return b.order-a.order; });
  return list.map(function(s){ return {key:s.key, label:s.label}; }).concat([{key:'all', label:'All time'}]);
}
// All-time games per player (final nights, every pool and squad): the public-visibility line.
function knAllTimeGames(){
  var out={};
  knFinalNights('all').forEach(function(n){
    knPoolsOf(n.meta).forEach(function(pool){
      ptStandingsIn(n.data,pool).forEach(function(r){ if(r.gp&&practiceEligibleId(r.id)) out[r.id]=(out[r.id]||0)+r.gp; });
    });
  });
  return out;
}
function knTonightActive(){
  var T=D.practiceTournaments||{}, today=td();
  return Object.keys(T).some(function(tid){ var m=(T[tid]&&T[tid].meta)||{}; return m.status==='active'&&m.date===today; });
}
// Totals per player, per pool and for All, over the period's final nights in the chosen squad.
// periodGames counts every pool and squad in the period and drives the default sort grouping.
function knTotals(squad,period){
  var out={};
  knFinalNights(period||'all').forEach(function(n){
    var inSquad=(squad==='all'||n.meta.squad===squad);
    knPoolsOf(n.meta).forEach(function(pool){
      ptStandingsIn(n.data,pool).forEach(function(r){
        if(!r.gp||!practiceEligibleId(r.id)) return;
        var t=out[r.id]||(out[r.id]={id:r.id, name:r.name, byPool:{}, all:{nights:0,games:0,w:0,l:0,pd:0}, seen:{}, periodGames:0});
        t.periodGames+=r.gp;
        if(!inSquad) return;
        var b=t.byPool[pool]||(t.byPool[pool]={nights:0,games:0,w:0,l:0,pd:0});
        b.nights++; b.games+=r.gp; b.w+=r.w; b.l+=r.l; b.pd+=r.pd;
        if(!t.seen[n.tid]){ t.seen[n.tid]=1; t.all.nights++; }
        t.all.games+=r.gp; t.all.w+=r.w; t.all.l+=r.l; t.all.pd+=r.pd;
      });
    });
  });
  return out;
}
function knIsTruVolley(id){
  var p=gP(id);
  if(p&&typeof p.truVolley==='number'&&typeof p.rating==='number') return true;
  return !!(_knSeeded&&_knSeeded[id]);
}
// One read of the rating records per page load, only to learn who carries a TruVolley seed there.
function knLoadSeeded(after){
  if(_knSeeded||_knSeededLoading||!db||!window.Ratings||typeof Ratings.nameKey!=='function') return;
  _knSeededLoading=true;
  db.ref('tally_kotb_pickup/ratings').once('value').then(function(s){
    var R=s.val()||{}, seeded={};
    (Array.isArray(D.players)?D.players:[]).forEach(function(p){
      if(!p||!p.id) return;
      var rec=ppFindRatingRecord(p,R);
      if(rec&&rec!=='ambiguous'&&rec.seededFromTruVolley!=null) seeded[p.id]=true;
    });
    _knSeeded=seeded;
  }).catch(function(e){ console.warn('kings night seed read failed',e); _knSeeded={}; })
    .then(function(){ _knSeededLoading=false; if(typeof after==='function') after(); });
}
// regular (5+ games in the period) drives the default sort grouping; isPublic (5+ games all time,
// or a TruVolley player) decides who other members can see.
function knRows(totals,pool,allTime){
  var at=allTime||{};
  return Object.keys(totals).map(function(id){
    var t=totals[id], s=(pool==='all')?t.all:t.byPool[pool];
    if(!s||!s.games) return null;
    return {id:id, name:t.name, nights:s.nights, games:s.games, w:s.w, l:s.l, pd:s.pd,
      pct:s.w/s.games*100, regular:t.periodGames>=KN_MIN_GAMES,
      isPublic:(at[id]||0)>=KN_MIN_GAMES||knIsTruVolley(id)};
  }).filter(Boolean);
}
// Default order: players with 5 or more games first, each group by win %, then +/-, then name.
// A header tap sorts everyone by that column alone, ties broken by +/- then name.
function knSortRows(rows,st){
  var tie=function(a,b){ return (b.pd-a.pd)||String(a.name).localeCompare(String(b.name)); };
  if(!st.sortKey) return rows.sort(function(a,b){ return ((b.regular?1:0)-(a.regular?1:0))||(b.pct-a.pct)||tie(a,b); });
  var k=st.sortKey, d=st.sortDir;
  return rows.sort(function(a,b){
    var c=(k==='name')?String(a.name).localeCompare(String(b.name)):(a[k]-b[k]);
    return (c*d)||tie(a,b);
  });
}
function knSortBy(ctx,key){
  var st=_knState[ctx];
  if(st.sortKey===key) st.sortDir=-st.sortDir;
  else { st.sortKey=key; st.sortDir=(key==='name')?1:-1; }
  knRerender(ctx);
}
function knSet(ctx,field,val){
  var st=_knState[ctx]; st[field]=val;
  if(field==='squad'||field==='period') st.night=null;
  knRerender(ctx);
}
function knRerender(ctx){
  knRender(document.getElementById(ctx==='exec'?'tab-players':'pp-panel-kings'),ctx);
}
function knRefreshPlayer(){
  if(currentRole!=='player'||!SC.tiersEnabled) return;
  var el=document.getElementById('pp-panel-kings');
  if(el&&el.classList.contains('active')) knRender(el,'player');
}
function knGoPractice(){
  var t=document.querySelector('.tab[data-tab="teamanalysis"]'); if(t) t.click();
}
function knRender(el,ctx){
  if(!el||!SC.tiersEnabled) return;
  var st=_knState[ctx];
  var esc=function(s){ return String(s==null?'':s).replace(/[&<>"']/g,function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]); }); };
  knLoadSeeded(function(){ knRerender(ctx); });
  var pill=function(field,v,lbl){
    return '<button class="filter-btn'+(st[field]===v?' active':'')+'" style="flex:1;text-align:center;padding:6px 4px;" onclick="knSet(\''+ctx+'\',\''+field+'\',\''+v+'\')">'+lbl+'</button>';
  };
  var me=(ctx==='player')?currentPlayerId:null;
  var html='<div class="card"><div class="card-title"><span class="bar"></span> \u{1F451} Kings Night</div>';
  if(knTonightActive()){
    html+='<div style="font-size:12px;color:var(--charcoal);background:var(--primary-bg,#f3e9eb);border-radius:8px;padding:8px 10px;margin-bottom:10px;">Tonight in progress. '
      +(ctx==='exec'?'<a href="javascript:void(0)" onclick="knGoPractice()" style="color:var(--red);font-weight:700;">Open the Practice tab</a> for live scores.':'Your live games are on the Kings Night card above.')+'</div>';
  }
  var period=knPeriodOf(st), periods=knPeriods();
  if(!periods.some(function(p){ return p.key===period; })){ st.period=null; period=knPeriodOf(st); }
  var periodLabel=periods.filter(function(p){ return p.key===period; })[0].label;
  var anyNights=knFinalNights('all').length>0;
  var nights=knFinalNights(period);
  var totals=knTotals(st.squad,period);
  var allTime=knAllTimeGames();
  if(me){
    var mine=knTotals('all',period)[me];
    html+='<div style="border:1px solid var(--gray-lighter);border-radius:10px;padding:10px 12px;margin-bottom:10px;">'
      +'<div style="font-family:\'Bebas Neue\',sans-serif;font-size:14px;letter-spacing:1px;color:var(--charcoal);margin-bottom:4px;">YOUR KINGS NIGHTS</div>';
    if(mine&&mine.all.games){
      var a=mine.all;
      html+='<div style="font-size:14px;color:var(--charcoal);">'+a.nights+' night'+(a.nights===1?'':'s')+' · '+a.games+' games · '
        +a.w+'-'+a.l+' · '+(a.pd>0?'+':'')+a.pd+' · '+Math.round(a.w/a.games*100)+'%</div>';
      if((allTime[me]||0)<KN_MIN_GAMES&&!knIsTruVolley(me)) html+='<div style="font-size:11px;color:var(--gray);margin-top:4px;">Only you can see this. You join the club leaderboard after '+KN_MIN_GAMES+' games.</div>';
    } else html+='<div style="font-size:13px;color:var(--gray);">No finished Kings Nights for you in '+esc(periodLabel)+'.</div>';
    html+='</div>';
  }
  html+='<select class="form-select" onchange="knSet(\''+ctx+'\',\'period\',this.value)" style="width:100%;padding:8px;font-size:13px;margin-bottom:8px;">'
    +periods.map(function(p){ return '<option value="'+esc(p.key)+'"'+(p.key===period?' selected':'')+'>'+esc(p.label)+'</option>'; }).join('')+'</select>'
    +'<div style="display:flex;gap:6px;margin-bottom:8px;">'+pill('view','season','Season')+pill('view','nights','Nights')+'</div>'
    +'<div style="display:flex;gap:6px;margin-bottom:8px;">'+pill('squad','gold','Gold')+pill('squad','garnet','Garnet')+pill('squad','all','All')+'</div>';
  if(!anyNights){
    el.innerHTML=html+'<div style="font-size:13px;color:var(--gray);padding:10px 0;">No Kings Nights finished yet.</div></div>';
    return;
  }
  if(!nights.length){
    el.innerHTML=html+'<div style="font-size:13px;color:var(--gray);padding:10px 0;">No finished Kings Nights in '+esc(periodLabel)+' yet.</div></div>';
    return;
  }
  var th='padding:6px 4px;font-weight:600;white-space:nowrap;', td2='padding:7px 4px;text-align:center;';
  if(st.view==='season'){
    html+='<div style="display:flex;gap:6px;margin-bottom:10px;">'+pill('pool','kings','Kings')+pill('pool','queens','Queens')+pill('pool','mixed','Coed')+pill('pool','all','All')+'</div>';
    var rows=knRows(totals,st.pool,allTime);
    if(ctx==='player') rows=rows.filter(function(r){ return r.isPublic||r.id===me; });
    knSortRows(rows,st);
    var cols=[['name','Player'],['nights','Nights'],['games','Games'],['w','W'],['l','L'],['pd','+/-'],['pct','Win %']];
    var arrow=function(k){
      var on=st.sortKey?st.sortKey===k:k==='pct';
      if(!on) return '';
      var d=st.sortKey?st.sortDir:-1;
      return d>0?' ▲':' ▼';
    };
    if(!rows.length){ html+='<div style="font-size:13px;color:var(--gray);padding:10px 0;">No games in this view yet.</div></div>'; el.innerHTML=html; return; }
    html+='<div style="overflow-x:auto;-webkit-overflow-scrolling:touch;"><table style="width:100%;min-width:420px;border-collapse:collapse;font-size:13px;"><thead><tr style="color:var(--gray);text-align:left;">'
      +'<th style="'+th+'">#</th>'
      +cols.map(function(c){ return '<th style="'+th+(c[0]==='name'?'':'text-align:center;')+'cursor:pointer;" onclick="knSortBy(\''+ctx+'\',\''+c[0]+'\')">'+c[1]+arrow(c[0])+'</th>'; }).join('')
      +'</tr></thead><tbody>'
      +rows.map(function(r,i){
        var mark=(ctx==='exec'&&!r.isPublic)?' <span style="font-size:10px;color:var(--gray);">under '+KN_MIN_GAMES+' games</span>':'';
        return '<tr style="border-top:1px solid var(--gray-lighter);color:var(--charcoal);'+(r.id===me?'font-weight:700;background:var(--primary-bg,#f3e9eb);':'')+'">'
          +'<td style="padding:7px 4px;color:var(--gray);">'+(i+1)+'</td>'
          +'<td style="padding:7px 4px;">'+esc(r.name)+mark+'</td>'
          +'<td style="'+td2+'">'+r.nights+'</td><td style="'+td2+'">'+r.games+'</td>'
          +'<td style="'+td2+'">'+r.w+'</td><td style="'+td2+'">'+r.l+'</td>'
          +'<td style="'+td2+'color:'+(r.pd>0?'#217F7F':r.pd<0?'var(--red)':'var(--gray)')+';">'+(r.pd>0?'+':'')+r.pd+'</td>'
          +'<td style="'+td2+'">'+Math.round(r.pct)+'%</td></tr>';
      }).join('')
      +'</tbody></table></div>';
  } else {
    var list=nights.filter(function(n){ return st.squad==='all'||n.meta.squad===st.squad; });
    if(!list.length){ el.innerHTML=html+'<div style="font-size:13px;color:var(--gray);padding:10px 0;">No finished Kings Nights for this squad yet.</div></div>'; return; }
    var pick=list.filter(function(n){ return n.tid===st.night; })[0]||list[0];
    st.night=pick.tid;
    html+='<select class="form-select" onchange="knSet(\''+ctx+'\',\'night\',this.value)" style="width:100%;padding:8px;font-size:13px;margin-bottom:10px;">'
      +list.map(function(n){
        var label=(tsReadableDate(n.meta.date)||n.meta.date||'')+(n.meta.squad?' · '+(TS_SQUAD_LABELS[n.meta.squad]||n.meta.squad):'');
        return '<option value="'+esc(n.tid)+'"'+(n.tid===pick.tid?' selected':'')+'>'+esc(label)+'</option>';
      }).join('')+'</select>';
    knPoolsOf(pick.meta).forEach(function(pool){
      var st2=ptStandingsIn(pick.data,pool).filter(function(r){ return r.gp>0&&practiceEligibleId(r.id); });
      html+='<div style="font-family:\'Bebas Neue\',sans-serif;font-size:13px;letter-spacing:1px;color:var(--charcoal);margin:6px 0 4px;">'+esc(KN_POOL_LABELS[pool].toUpperCase())+'</div>';
      if(!st2.length){ html+='<div style="font-size:12px;color:var(--gray);margin-bottom:8px;">No games scored.</div>'; return; }
      html+='<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:10px;"><thead><tr style="color:var(--gray);text-align:left;">'
        +'<th style="'+th+'">#</th><th style="'+th+'">Player</th><th style="'+th+'text-align:center;">W</th><th style="'+th+'text-align:center;">L</th><th style="'+th+'text-align:center;">+/-</th><th style="'+th+'text-align:center;">GP</th></tr></thead><tbody>'
        +st2.map(function(x,i){
          return '<tr style="border-top:1px solid var(--gray-lighter);color:var(--charcoal);'+(x.id===me?'font-weight:700;background:var(--primary-bg,#f3e9eb);':'')+'">'
            +'<td style="padding:6px 4px;color:var(--gray);">'+(i+1)+'</td>'
            +'<td style="padding:6px 4px;">'+esc(x.name)+(x.dropped?' <span style="font-size:10px;color:var(--gray);">(left)</span>':'')+'</td>'
            +'<td style="'+td2+'">'+x.w+'</td><td style="'+td2+'">'+x.l+'</td>'
            +'<td style="'+td2+'color:'+(x.pd>0?'#217F7F':x.pd<0?'var(--red)':'var(--gray)')+';">'+(x.pd>0?'+':'')+x.pd+'</td>'
            +'<td style="'+td2+'">'+x.gp+'</td></tr>';
        }).join('')
        +'</tbody></table></div>';
    });
  }
  el.innerHTML=html+'</div>';
}
function renderPlayerPortal(){
  if(!currentPlayerId)return;
  const p=gP(currentPlayerId);
  if(!p)return;
  const pid=currentPlayerId;
  processPendingTryout(); // record a pending door check-in once the member is logged in
  renderPlayerBroadcasts();
  if(SC.tiersEnabled&&typeof renderPlayerPinned==='function')renderPlayerPinned();
  if(SC.tiersEnabled&&typeof ptpSync==='function')ptpSync();
  if(SC.tiersEnabled)ppRenderRating();
  if(SC.tiersEnabled&&typeof updateMemberMsgBadge==='function')updateMemberMsgBadge();

  document.getElementById('pp-name').textContent=p.firstName+' '+p.lastName;
  document.getElementById('pp-meta').innerHTML=`${p.jersey!=null?'<span style="font-family:\'Bebas Neue\',sans-serif;font-size:16px;color:var(--red);margin-right:6px;">#'+p.jersey+'</span>':''}<span class="class-badge class-${p.classYear}">${p.classYear}</span>`;

  // Player tier request (Grass Club only, gated on SC.tiersEnabled). Tier placement is set by the coach;
  // the player may ask to be considered for one. Writes to the SEPARATE tier_requests node, never to the player record.
  const tierReqEl=document.getElementById('pp-tier-request');
  if(tierReqEl){
    if(SC.tiersEnabled){
      const TIER_LABELS={gold:'Gold',garnet:'Garnet'};
      const req=(D.tierRequests||{})[pid];
      let rh=`<div class="card" style="padding:12px 14px;margin-top:10px;">
        <div style="font-family:'Bebas Neue';font-size:13px;letter-spacing:1px;color:var(--charcoal);margin-bottom:4px;">Tier Placement</div>
        <div style="font-size:12px;color:var(--gray);margin-bottom:10px;line-height:1.5;">Your coach sets your tier. You can ask to be considered for one below. This is a request, not a final placement.</div>
        <div style="font-size:12px;color:var(--charcoal);margin-bottom:10px;line-height:1.5;">Gold is our entry level squad, a great place to start and grow. Garnet is for experienced players ready for a higher level of play.</div>`;
      if(req&&req.tier){
        rh+=`<div style="font-size:13px;margin-bottom:10px;">You requested: <span class="tier-badge tier-${req.tier}">${TIER_LABELS[req.tier]||req.tier}</span> <span style="color:var(--gray);font-size:12px;">Your coach will review it.</span></div>`;
      }
      rh+=`<div style="display:flex;gap:8px;">
        <button class="btn btn-small" style="flex:1;background:#CEB888;color:#2d2d2d;border:none;" onclick="playerRequestTier('gold')">Request Gold (entry level)</button>
        <button class="btn btn-small" style="flex:1;background:#782F40;color:#ffffff;border:none;" onclick="playerRequestTier('garnet')">Request Garnet (experienced)</button>
      </div></div>`;
      tierReqEl.innerHTML=rh;
    } else {
      tierReqEl.innerHTML='';
    }
  }
  const _ppPr=document.getElementById('pp-practice'); if(_ppPr) _ppPr.innerHTML=memberPracticeHtml(p);

  // Summary stats — filtered by ppStatView
  const qs=queensStats(pid,D.matches);
  const _gdFiltered=ppStatView==='exhibition'?(D.gamedays||[]).filter(m=>(m.court||0)>5):(D.gamedays||[]).filter(m=>(m.court||0)<=5||!(m.court));
  const gs=extStats(pid,_gdFiltered);
  const ss=extStats(pid,D.scrimmages);
  const _psum=document.getElementById('pp-summary');if(_psum)_psum.innerHTML=`
    <div style="grid-column:1/-1;display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:4px;">
      <div class="stat-box"><div class="stat-number green">${gs.matchesWon}-${gs.matchesLost}</div><div class="stat-label">Match W-L</div></div>
      <div class="stat-box"><div class="stat-number green">${gs.setsWon}-${gs.setsLost}</div><div class="stat-label">Set W-L</div></div>
      <div class="stat-box"><div class="stat-number ${pmClass(gs.diff)}">${gs.sets>0?pmStr(gs.diff):'—'}</div><div class="stat-label">Pts +/-</div></div>
    </div>
    <div style="grid-column:1/-1;display:grid;grid-template-columns:repeat(7,1fr);gap:6px;">
      <div class="stat-box"><div class="stat-number" style="font-size:22px;">${gs.k}</div><div class="stat-label">Kills</div></div>
      <div class="stat-box"><div class="stat-number" style="font-size:22px;">${gs.a}</div><div class="stat-label">Aces</div></div>
      <div class="stat-box"><div class="stat-number" style="font-size:22px;">${gs.b}</div><div class="stat-label">Blocks</div></div>
      <div class="stat-box"><div class="stat-number" style="font-size:22px;">${gs.se}</div><div class="stat-label">Srv Err</div></div>
      <div class="stat-box"><div class="stat-number" style="font-size:22px;">${gs.re}</div><div class="stat-label">Rcv Err</div></div>
      <div class="stat-box"><div class="stat-number" style="font-size:22px;">${gs.he}</div><div class="stat-label">Hit Err</div></div>
      <div class="stat-box"><div class="stat-number" style="font-size:22px;">${gs.de}</div><div class="stat-label">Dig Err</div></div>
    </div>
    <div style="grid-column:1/-1;font-size:10px;color:var(--gray);text-align:center;margin-top:6px;letter-spacing:0.5px;">${ppStatView==="exhibition"?"EXHIBITION MATCHES (CT 6+)":"OFFICIAL DUAL MATCHES (CT 1-5)"}</div>`;

  // ===== TEAM RANKINGS (member-facing) =====
  // Club build: skill ranking is exec only, never shown to the general membership, so the whole
  // section is skipped for the club (its pp-rankings card is not rendered). High schools still show it.
  // The exec-side ranking (cpm-rankings, coach player modal) is a separate render path, unaffected.
  if(!SC.tiersEnabled){
  // Build stats for all players
  const allPlayers=D.players.filter(pl=>pl.id);
  const rankings=[];
  // Queens +/-
  const qRanks=allPlayers.map(pl=>{const s=queensStats(pl.id,D.matches);return{id:pl.id,val:s.diff,gp:s.gp};}).filter(r=>r.gp>0).sort((a,b)=>b.val-a.val);
  // Queens Win %
  const qWinRanks=allPlayers.map(pl=>{const s=queensStats(pl.id,D.matches);return{id:pl.id,val:s.pct,gp:s.gp};}).filter(r=>r.gp>0).sort((a,b)=>b.val-a.val);
  // Game Day +/-
  const gdRanks=allPlayers.map(pl=>{const s=extStats(pl.id,D.gamedays);return{id:pl.id,val:s.diff,sets:s.sets};}).filter(r=>r.sets>0).sort((a,b)=>b.val-a.val);
  // Game Day Kills
  const gdKillRanks=allPlayers.map(pl=>{const s=extStats(pl.id,D.gamedays);return{id:pl.id,val:s.k,sets:s.sets};}).filter(r=>r.sets>0).sort((a,b)=>b.val-a.val);
  // Game Day Aces
  const gdAceRanks=allPlayers.map(pl=>{const s=extStats(pl.id,D.gamedays);return{id:pl.id,val:s.a,sets:s.sets};}).filter(r=>r.sets>0).sort((a,b)=>b.val-a.val);
  // Combined +/-
  const totalRanks=allPlayers.map(pl=>{
    const q=queensStats(pl.id,D.matches),g=extStats(pl.id,D.gamedays),s=extStats(pl.id,D.scrimmages);
    const total=q.diff+g.diff+s.diff,gp=q.gp+g.matches+s.matches;
    return{id:pl.id,val:total,gp};
  }).filter(r=>r.gp>0).sort((a,b)=>b.val-a.val);

  function ordinal(n){const s=["th","st","nd","rd"],v=n%100;return n+(s[(v-20)%10]||s[v]||s[0]);}
  function rankHTML(label,ranksArr,pid,formatVal){
    const pos=ranksArr.findIndex(r=>r.id===pid);
    if(pos===-1)return'';
    const total=ranksArr.length;
    const rank=pos+1;
    const pct=total>1?((total-rank)/(total-1))*100:100;
    const myVal=ranksArr[pos].val;
    const barClass=rank<=3?'top3':rank<=Math.ceil(total/2)?'mid':'low';
    const valStr=formatVal?formatVal(myVal):(myVal>0?'+'+myVal:''+myVal);
    return`<div class="rank-row">
      <span class="rank-label">${label}</span>
      <div class="rank-bar-wrap"><div class="rank-bar-fill ${barClass}" style="width:${Math.max(8,pct)}%"></div></div>
      <span class="rank-value">${valStr}</span>
      <span class="rank-position">${ordinal(rank)} <span class="ordinal">of ${total}</span></span>
    </div>`;
  }

  let rHTML='';
  rHTML+='<div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:1.5px;color:var(--gray);margin:4px 0 8px;">Match Stats</div>';
  rHTML+=rankHTML('Queens +/-',qRanks,pid);
  rHTML+=rankHTML('Queens Win%',qWinRanks,pid,v=>Math.round(v)+'%');
  rHTML+=rankHTML('Game Day +/-',gdRanks,pid);
  rHTML+=rankHTML('GD Kills',gdKillRanks,pid,v=>''+v);
  rHTML+=rankHTML('GD Aces',gdAceRanks,pid,v=>''+v);
  rHTML+=rankHTML('Overall +/-',totalRanks,pid);

  rHTML+='<div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:1.5px;color:var(--gray);margin:16px 0 8px;">Athleticism</div>';

  // Star Drill ranking (lower is better — reverse sort)
  const drillData2=profilesData?.starDrills||{};
  const drillBests={};
  Object.values(drillData2).forEach(d=>{
    const did=d.playerId||d.player;if(!did)return;
    if(!drillBests[did]||d.time<drillBests[did])drillBests[did]=d.time;
  });
  console.log('Drill bests:',Object.keys(drillBests).length,'players, pid='+pid,'has data:',!!drillBests[pid]);
  const drillRanks=Object.entries(drillBests).map(([id,best])=>({id,val:best})).sort((a,b)=>a.val-b.val); // lower is better
  if(drillRanks.length>=1){
    // For drill, rank 1 = fastest, so we reverse the bar percentage
    const drillPos=drillRanks.findIndex(r=>r.id===pid);
    if(drillPos>=0){
      const total=drillRanks.length,rank=drillPos+1;
      const pct=total>1?((total-rank)/(total-1))*100:100;
      const barClass=rank<=3?'top3':rank<=Math.ceil(total/2)?'mid':'low';
      rHTML+=`<div class="rank-row"><span class="rank-label">Star Drill</span>
        <div class="rank-bar-wrap"><div class="rank-bar-fill ${barClass}" style="width:${Math.max(8,pct)}%"></div></div>
        <span class="rank-value">${drillBests[pid].toFixed(1)}s</span>
        <span class="rank-position">${ordinal(rank)} <span class="ordinal">of ${total}</span></span></div>`;
    }
  }

  // Vertical ranking (approach jump, higher is better)
  const vertData2=profilesData?.jumpTests||profilesData?.verticals||{};
  console.log('Vert data entries:',Object.keys(vertData2).length,'profilesData keys:',Object.keys(profilesData||{}).join(','));
  const vertBests={};
  Object.values(vertData2).forEach(v=>{
    const vid=v.playerId||v.player;if(!vid)return;
    const approach=v.approachJump||v.approach||v.approachJumpTouch||'';
    if(approach){
      // Convert to inches for comparison: parse "8'6" format
      const inches=parseHeight(approach);
      if(inches&&(!vertBests[vid]||inches>vertBests[vid].inches)){vertBests[vid]={inches,display:approach};}
    }
  });
  function parseHeight(s){if(!s)return 0;s=String(s);const m=s.match(/(\d+)\D+(\d+)/);if(!m)return 0;return parseInt(m[1])*12+(parseInt(m[2])||0);}
  const vertRanks=Object.entries(vertBests).map(([id,v])=>({id,val:v.inches,display:v.display})).sort((a,b)=>b.val-a.val);
  if(vertRanks.length>=1){
    const vertPos=vertRanks.findIndex(r=>r.id===pid);
    if(vertPos>=0){
      const total=vertRanks.length,rank=vertPos+1;
      const pct=total>1?((total-rank)/(total-1))*100:100;
      const barClass=rank<=3?'top3':rank<=Math.ceil(total/2)?'mid':'low';
      rHTML+=`<div class="rank-row"><span class="rank-label">Approach Jump</span>
        <div class="rank-bar-wrap"><div class="rank-bar-fill ${barClass}" style="width:${Math.max(8,pct)}%"></div></div>
        <span class="rank-value">${vertRanks[vertPos].display}</span>
        <span class="rank-position">${ordinal(rank)} <span class="ordinal">of ${total}</span></span></div>`;
    }
  }

  // Block jump ranking
  const blockBests={};
  Object.values(vertData2).forEach(v=>{
    const vid=v.playerId||v.player;if(!vid)return;
    const block=v.blockJump||v.block||v.blockJumpTouch||'';
    if(block){const inches=parseHeight(block);if(inches&&(!blockBests[vid]||inches>blockBests[vid].inches)){blockBests[vid]={inches,display:block};}}
  });
  const blockRanks=Object.entries(blockBests).map(([id,v])=>({id,val:v.inches,display:v.display})).sort((a,b)=>b.val-a.val);
  if(blockRanks.length>=1){
    const blockPos=blockRanks.findIndex(r=>r.id===pid);
    if(blockPos>=0){
      const total=blockRanks.length,rank=blockPos+1;
      const pct=total>1?((total-rank)/(total-1))*100:100;
      const barClass=rank<=3?'top3':rank<=Math.ceil(total/2)?'mid':'low';
      rHTML+=`<div class="rank-row"><span class="rank-label">Block Jump</span>
        <div class="rank-bar-wrap"><div class="rank-bar-fill ${barClass}" style="width:${Math.max(8,pct)}%"></div></div>
        <span class="rank-value">${blockRanks[blockPos].display}</span>
        <span class="rank-position">${ordinal(rank)} <span class="ordinal">of ${total}</span></span></div>`;
    }
  }

  // Standing reach ranking (higher is better)
  const reachBests={};
  Object.values(vertData2).forEach(v=>{
    const vid=v.playerId||v.player;if(!vid)return;
    const reach=v.standingReach||v.reach||'';
    if(reach){const inches=parseHeight(reach);if(inches&&(!reachBests[vid]||inches>reachBests[vid].inches)){reachBests[vid]={inches,display:reach};}}
  });
  const reachRanks=Object.entries(reachBests).map(([id,v])=>({id,val:v.inches,display:v.display})).sort((a,b)=>b.val-a.val);
  if(reachRanks.length>=1){
    const reachPos=reachRanks.findIndex(r=>r.id===pid);
    if(reachPos>=0){
      const total=reachRanks.length,rank=reachPos+1;
      const pct=total>1?((total-rank)/(total-1))*100:100;
      const barClass=rank<=3?'top3':rank<=Math.ceil(total/2)?'mid':'low';
      rHTML+=`<div class="rank-row"><span class="rank-label">Standing Reach</span>
        <div class="rank-bar-wrap"><div class="rank-bar-fill ${barClass}" style="width:${Math.max(8,pct)}%"></div></div>
        <span class="rank-value">${reachRanks[reachPos].display}</span>
        <span class="rank-position">${ordinal(rank)} <span class="ordinal">of ${total}</span></span></div>`;
    }
  }

  // Height ranking (higher is better)
  const heightData={};
  allPlayers.forEach(pl=>{
    const pp=profilesData?.players?.[pl.id]||{};
    const h=pp.height||'';
    if(h){const inches=parseHeight(h);if(inches)heightData[pl.id]={inches,display:h};}
  });
  const heightRanks=Object.entries(heightData).map(([id,v])=>({id,val:v.inches,display:v.display})).sort((a,b)=>b.val-a.val);
  if(heightRanks.length>=1){
    const heightPos=heightRanks.findIndex(r=>r.id===pid);
    if(heightPos>=0){
      const total=heightRanks.length,rank=heightPos+1;
      const pct=total>1?((total-rank)/(total-1))*100:100;
      const barClass=rank<=3?'top3':rank<=Math.ceil(total/2)?'mid':'low';
      rHTML+=`<div class="rank-row"><span class="rank-label">Height</span>
        <div class="rank-bar-wrap"><div class="rank-bar-fill ${barClass}" style="width:${Math.max(8,pct)}%"></div></div>
        <span class="rank-value">${heightRanks[heightPos].display}</span>
        <span class="rank-position">${ordinal(rank)} <span class="ordinal">of ${total}</span></span></div>`;
    }
  }

  // Skill rankings — average and individual
  rHTML+='<div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:1.5px;color:var(--gray);margin:16px 0 8px;">Skills</div>';
  const skillNames=['serving','passing','setting','hitting','blocking','defense','courtSense','communication'];
  const skillLabels={serving:'Serving',passing:'Passing',setting:'Setting',hitting:'Hitting',blocking:'Blocking',defense:'Defense',courtSense:'Court Sense',communication:'Communication'};
  const playerSkills={};
  allPlayers.forEach(pl=>{
    const sk=profilesData?.skills?.[pl.id]||profilesData?.players?.[pl.id]?.skills||{};
    const hasSkills=skillNames.some(k=>sk[k]>0);
    if(hasSkills)playerSkills[pl.id]=sk;
  });

  // Average skill ranking
  const avgSkillRanks=Object.entries(playerSkills).map(([id,sk])=>{
    const avg=skillNames.reduce((s,k)=>s+(sk[k]||0),0)/skillNames.length;
    return{id,val:avg};
  }).sort((a,b)=>b.val-a.val);
  rHTML+=rankHTML('Avg Skill Rating',avgSkillRanks,pid,v=>v.toFixed(1));

  // Individual skill rankings
  skillNames.forEach(sk=>{
    const skRanks=Object.entries(playerSkills).map(([id,skills])=>({id,val:skills[sk]||0})).filter(r=>r.val>0).sort((a,b)=>b.val-a.val);
    if(skRanks.length>1)rHTML+=rankHTML(skillLabels[sk],skRanks,pid,v=>''+v);
  });

  document.getElementById('pp-rankings').innerHTML=rHTML||'<div style="color:var(--gray);font-size:13px;text-align:center;padding:16px;"><div style="font-size:28px;margin-bottom:8px;">📊</div>Rankings will appear here as match data is recorded.</div>';
  } // end !SC.tiersEnabled team rankings

  // Queens matches
  const myQ=D.matches.filter(m=>(m.team1||[]).includes(pid)||(m.team2||[]).includes(pid))
    .sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  if(myQ.length){
    let h='';
    myQ.forEach(m=>{
      const onT1=(m.team1||[]).includes(pid);
      const partner=onT1?(m.team1||[]).find(x=>x!==pid):(m.team2||[]).find(x=>x!==pid);
      const opps=onT1?(m.team2||[]):(m.team1||[]);
      const myScore=onT1?(m.score1||0):(m.score2||0);
      const theirScore=onT1?(m.score2||0):(m.score1||0);
      const win=myScore>theirScore;
      const diff=myScore-theirScore;
      h+=`<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid rgba(0,0,0,0.05);">
        <div><div style="font-size:12px;color:var(--gray);">${fD(m.date)} · Court ${m.court}</div>
          <div style="font-size:13px;font-weight:700;">w/ ${pN(partner)} vs ${opps.map(id=>pN(id)).join(' & ')}</div></div>
        <div style="text-align:right;">
          <div class="set-score ${win?'win':'loss'}" style="font-size:20px;">${myScore}-${theirScore}</div>
          <div class="plus-minus ${pmClass(diff)}" style="font-size:13px;">${pmStr(diff)}</div></div></div>`;
    });
    document.getElementById('pp-queens').innerHTML=h;
  }else{
    document.getElementById('pp-queens').innerHTML='<div style="color:var(--gray);font-size:13px;text-align:center;padding:12px;">No Queens matches yet</div>';
  }

  // Schedule, standings, goals, assignment for player
  renderPlayerSchedule();
  renderPlayerGoals();
  renderPlayerAssignment(pid);
  // Profile data (skills, drills, verticals, notes)
  renderPlayerProfileData(pid);
  // Always refresh scouts so data shows without needing a tab click
  renderPlayerScouts();
  // If matches tab is active, render it too
  const activeTab=document.querySelector('.pp-tab-btn.active');
  if(activeTab&&activeTab.textContent.includes('My Matches'))renderPlayerMatches();
  if(activeTab&&activeTab.textContent.includes('Live Dual'))renderPlayerLiveScoring();
}

function renderPlayerSchedule(){
  const games=[...D.schedule.filter(inSeason)].sort((a,b)=>(a.date||'').localeCompare(b.date||''));
  if(!games.length){const _pe=document.getElementById('pp-schedule');if(_pe)_pe.innerHTML='<div style="color:var(--gray);font-size:13px;text-align:center;padding:12px;">No schedule yet.</div>';return;}
  const today=td();
  let h='';
  games.forEach(g=>{
    const played=g.scoreUs!=null&&g.scoreThem!=null&&g.scoreUs!==''&&g.scoreThem!=='';
    const win=played&&g.scoreUs>g.scoreThem;
    const upcoming=!played&&g.date>=today;
    const loc=g.location==='away'?'@':'vs';
    h+=`<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid rgba(0,0,0,0.04);">
      <div style="min-width:55px;font-size:12px;color:var(--gray);font-weight:600;">${fD(g.date)}</div>
      <div style="flex:1;"><span style="font-size:11px;color:var(--gray);">${loc}</span> <span style="font-weight:700;font-size:13px;">${g.opponent||'TBD'}</span>
        ${g.time&&upcoming?'<span style="font-size:11px;color:var(--gray);margin-left:4px;">'+g.time+'</span>':''}</div>
      <div style="min-width:40px;text-align:right;">`;
    if(played){h+=`<span style="font-family:'Bebas Neue';font-size:16px;color:${win?'var(--green)':'var(--loss-red)'};">${g.scoreUs}-${g.scoreThem}</span>`;}
    else if(upcoming){h+='<span style="font-size:11px;color:var(--gray);">TBD</span>';}
    h+='</div></div>';
  });
  const _pe2=document.getElementById('pp-schedule');if(_pe2)_pe2.innerHTML=h;
  // Player standings view
  renderPlayerStandings();
}

function renderPlayerStandings(){
  const games=[...D.schedule.filter(inSeason)];
  let leonW=0,leonL=0;
  const oppFromSchedule={};
  games.forEach(g=>{
    if(g.scoreUs!=null&&g.scoreThem!=null){
      g.scoreUs>g.scoreThem?leonW++:leonL++;
      const opp=g.opponent||'';
      if(opp){if(!oppFromSchedule[opp])oppFromSchedule[opp]={w:0,l:0};g.scoreUs>g.scoreThem?oppFromSchedule[opp].l++:oppFromSchedule[opp].w++;}
    }
  });
  const teams={};
  Object.entries(oppFromSchedule).forEach(([name,rec])=>{teams[name]={w:rec.w,l:rec.l,auto:true};});
  Object.entries(D.standings).forEach(([name,s])=>{teams[name]={w:s.w||0,l:s.l||0,auto:false};});
  teams[SC.myStandingsKey]={w:leonW,l:leonL,auto:true};
  const sorted=Object.entries(teams).sort((a,b)=>{
    const pctA=(a[1].w+a[1].l)>0?a[1].w/(a[1].w+a[1].l):0;
    const pctB=(b[1].w+b[1].l)>0?b[1].w/(b[1].w+b[1].l):0;
    return pctB-pctA||b[1].w-a[1].w;
  });
  if(!sorted.length){const _pst=document.getElementById('pp-standings');if(_pst)_pst.innerHTML='<div style="color:var(--gray);font-size:13px;text-align:center;padding:12px;">No standings data yet.</div>';return;}
  let h='<table class="player-table"><thead><tr><th>#</th><th>Team</th><th>W</th><th>L</th><th>Pct</th></tr></thead><tbody>';
  sorted.forEach(([name,s],i)=>{
    const pct=(s.w+s.l)>0?((s.w/(s.w+s.l))*100).toFixed(0)+'%':'—';
    const isMine=_isOwnStanding(name);
    h+=`<tr style="${isMine?'background:var(--red-bg);font-weight:700;':''}">
      <td style="font-family:'Bebas Neue';font-size:14px;color:var(--gray);">${i+1}</td>
      <td style="${isMine?'color:var(--red);':''}font-weight:700;">${name}${isMine?' '+(SC.teamEmoji||''):''}</td>
      <td style="font-family:'Bebas Neue';font-size:16px;color:var(--green);">${s.w}</td>
      <td style="font-family:'Bebas Neue';font-size:16px;color:var(--loss-red);">${s.l}</td>
      <td style="font-family:'Bebas Neue';font-size:14px;">${pct}</td></tr>`;
  });
  h+='</tbody></table>';
  const _pst2=document.getElementById('pp-standings');if(_pst2)_pst2.innerHTML=h;
}

function renderPlayerExtMatches(pid,matchList,containerId){
  const myM=matchList.filter(m=>(m.pair||[]).includes(pid)).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  if(!myM.length){
    document.getElementById(containerId).innerHTML='<div style="color:var(--gray);font-size:13px;text-align:center;padding:12px;">No matches yet</div>';
    return;
  }
  let h='';
  myM.forEach(m=>{
    const partner=(m.pair||[]).find(x=>x!==pid);
    const sets=m.sets||[];
    let sw=0,sl=0,mDiff=0;
    h+=`<div style="padding:10px 0;border-bottom:1px solid rgba(0,0,0,0.05);">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
        <div><div style="font-size:12px;color:var(--gray);">${fD(m.date)} · Court ${m.court||1}</div>
          <div style="font-size:13px;font-weight:700;">w/ ${pN(partner)} vs ${m.opponent||'TBD'}</div></div></div>`;
    if(sets.length){
      sets.forEach((s,i)=>{
        const su=s.scoreUs||0,st=s.scoreThem||0,win=su>st;
        su>st?sw++:sl++;mDiff+=(su-st);
        const ps=s.stats?.[pid]||{};
        const statParts=[];if(ps.k)statParts.push(ps.k+'K');if(ps.b)statParts.push(ps.b+'B');if(ps.a)statParts.push(ps.a+'A');if(ps.d)statParts.push(ps.d+'D');if(ps.e)statParts.push(ps.e+'E');
        h+=`<div class="set-row"><span class="set-label">S${i+1}</span><span class="set-score ${win?'win':'loss'}">${su}-${st}</span>
          ${statParts.length?'<span class="set-stats-mini">'+statParts.join(', ')+'</span>':''}</div>`;
      });
      h+=`<div style="display:flex;gap:12px;margin-top:6px;font-family:'Bebas Neue';font-size:14px;">
        <span>Sets: <strong>${sw}-${sl}</strong></span>
        <span class="plus-minus ${pmClass(mDiff)}">${pmStr(mDiff)}</span></div>`;
    }else{
      h+='<div style="font-size:12px;color:var(--gray);font-style:italic;">No sets recorded</div>';
    }
    h+='</div>';
  });
  document.getElementById(containerId).innerHTML=h;
}

